// Builds the wasm kernels with zig and embeds them as base64 modules (src/wasm/*.mjs). The generated files are committed, zig is only needed to rebuild.
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { gzipSync } from "node:zlib";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const targets = [
  { name: "scalar", source: "zig/fast4.zig", flags: [] },
  { name: "simd", source: "zig/simd7.zig", flags: ["-mcpu=generic+simd128"] },
  { name: "simd-transposition", source: "zig/simd7d.zig", flags: ["-mcpu=generic+simd128"] },   // loaded on demand, only for typing.transposition
  { name: "simd-weighted", source: "zig/simd7w.zig", flags: ["-mcpu=generic+simd128"] },   // loaded on demand, only for typing.firstLetter
  { name: "simd-weighted-transposition", source: "zig/simd7wd.zig", flags: ["-mcpu=generic+simd128"] },
];

mkdirSync(root + "wasm", { recursive: true });   // wasm/ is not committed

for (const { name, source, flags } of targets) {
  const bin = `wasm/${name}.wasm`;
  execFileSync("zig", ["build-exe", source, "-target", "wasm32-freestanding", ...flags, "-O", process.env.ZIG_OPT ?? "ReleaseFast", "-fno-entry", "-rdynamic", "-fstrip", `-femit-bin=${bin}`], { cwd: root, stdio: "inherit" });
  const bytes = readFileSync(root + bin);
  writeFileSync(`${root}src/wasm/${name}.mjs`, `// Generated by scripts/build-wasm.mjs from ${source}. Do not edit.\nexport default "${bytes.toString("base64")}";\n`);
  console.log(`${name}: ${bytes.length} bytes, ${gzipSync(bytes).length} gzipped`);
}
